documents.keyed_donor:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: {path: input.csv, types: {VALUE: int}}
  D: {path: donor.csv, key: [ID], types: {REFERENCE: int}}
output: {path: output.csv, columns: [ID, TOTAL, REFERENCE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: TOTAL, type: int}
  - {name: REFERENCE, type: int, derivation: D.REFERENCE}
rows:
  - id: grouped
    dataset: SRC
    group_by: [SRC.ID]
    derivations: {TOTAL: {aggregate: 'SUM(SRC.VALUE)'}}

