files.spec.yaml:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: input.csv, types: {VALUE: int}}
  D: donor.csv
intermediates: [{id: P, dataset: D, key: [ID]}]
output: {path: output.csv, columns: [ID, SEQ, VALUE, PICK]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: int, derivation: SRC.VALUE}
  - {name: SEQ, type: int, derivation: {row_number: {window: {group_by: [ID], order_by: [VALUE]}}}}
  - {name: PICK, type: str, derivation: P.PICK}
rows:
  - {id: first, dataset: SRC, filter: "SRC.KIND = 'A'"}
  - {id: second, dataset: SRC, filter: "SRC.KIND = 'B'"}

yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: input.csv}
output: {path: output.csv, columns: [ID, VALUE, TEXT]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: int, derivation: 'EXP(0) + LN(1) + POWER(3, 2)'}
  - {name: PICK, type: str, derivation: {first_available: {sources: [ID], missing: fallback}}}
  - name: TEXT
    type: str
    derivation:
      case:
        - when: VALUE = 10
          then: {str_template: 'prefix:{PICK}'}
        - otherwise: "'wrong'"

yamaa: "1.0"
type: spec
domain: TEST
keys: [ID, SECTION]
input:
  ALPHA: {path: input.csv, types: {ID: int, S: int}}
  BETA: {path: beta.csv, types: {OTHER: int, AMOUNT: float}}
output: {path: output.csv, columns: [ID, SECTION, SEQ, GLOBAL, TOTAL]}
columns:
- {name: ID, type: int}
- {name: SECTION, type: str}
- {name: SEQ, type: int}
- {name: GLOBAL, type: int, derivation: {row_number: {window: {order_by: [ID, SECTION]}}}}
- {name: TOTAL, type: float}
rows:
- id: records
  dataset: ALPHA
  filter: 'ID > 1'
  derivations:
    ID: ALPHA.ID
    SECTION: "'A'"
    SEQ: {row_number: {window: {order_by: [{variable: ID, direction: desc}]}}}
    TOTAL: 0
- id: groups
  dataset: BETA
  group_by: [BETA.OTHER]
  derivations:
    ID: BETA.OTHER
    SECTION: "'B'"
    SEQ: {row_number: {window: {order_by: [{variable: ID, direction: desc}]}}}
    TOTAL: {aggregate: 'SUM(BETA.AMOUNT)'}

yamaa: "1.0"
type: spec
domain: TEST
keys: [ID, SECTION]
input: {SRC: {path: input.csv, types: {I: int}}}
output: {path: output.csv, columns: [ID, SECTION, VALUE]}
columns:
- {name: ID, type: int}
- {name: SECTION, type: str, derivation: "'S'"}
- {name: VALUE, type: float, derivation: 'POWER(ID, 2)'}
rows:
- id: selected
  filter: 'VALUE > 4'
  derivations: {ID: SRC.I}

yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {I: int, V: float}}}
output: {path: output.csv, columns: [ID, TOTAL, SEQ]}
columns:
- {name: ID, type: int}
- {name: TOTAL, type: float}
- {name: SEQ, type: int}
rows:
- id: selected
  group_by: [SRC.I]
  filter: 'SEQ = 2 AND TOTAL = 7'
  derivations:
    ID: SRC.I
    TOTAL: {aggregate: 'SUM(SRC.V)'}
    SEQ: {row_number: {window: {order_by: [{variable: ID, direction: desc}]}}}
